using System.Collections.Generic;
using System.Linq;
using BTDB.ODBLayer;
using Xunit;
using Xunit.Abstractions;

namespace BTDBTest;

/// Runtime regressions of relation implementations generated by BTDB.SourceGenerator.
public class ObjectDbTableSourceGeneratorRegressionTest : ObjectDbTestBase
{
    public ObjectDbTableSourceGeneratorRegressionTest(ITestOutputHelper output) : base(output)
    {
    }

    public class Person
    {
        [PrimaryKey(1)] public ulong TenantId { get; set; }
        [PrimaryKey(2)] public ulong Id { get; set; }
        [SecondaryKey("Name")] public string Name { get; set; } = "";
    }

    public interface IPersonTable : IRelation<Person>
    {
        ICollection<Person> FindById(ulong tenantId);
        IReadOnlyCollection<Person> FindByName(string name);
    }

    [Fact]
    public void FindByCanReturnCollections()
    {
        using var tr = _db.StartTransaction();
        var table = tr.GetRelation<IPersonTable>();
        table.Upsert(new() { TenantId = 1, Id = 1, Name = "A" });
        table.Upsert(new() { TenantId = 1, Id = 2, Name = "B" });
        table.Upsert(new() { TenantId = 2, Id = 3, Name = "A" });

        var byTenant = table.FindById(1);
        Assert.Equal(2, byTenant.Count);
        Assert.Equal(new ulong[] { 1, 2 }, byTenant.Select(p => p.Id));

        var byName = table.FindByName("A");
        Assert.Equal(2, byName.Count);
        Assert.Equal(new ulong[] { 1, 3 }, byName.Select(p => p.Id));
    }

    public class Price
    {
        [PrimaryKey(1)] public decimal Amount { get; set; }
        [SecondaryKey("Rate")] public decimal? Rate { get; set; }
        public decimal Other { get; set; }
    }

    public interface IPriceTable : IRelation<Price>
    {
        Price? FindByIdOrDefault(decimal amount);
        IEnumerable<Price> ListByRate(decimal? rate);
        bool UpdateById(decimal amount, decimal other);
    }

    [Fact]
    public void DecimalKeysAndUpdateByIdValuesWork()
    {
        using var tr = _db.StartTransaction();
        var table = tr.GetRelation<IPriceTable>();
        table.Upsert(new() { Amount = 1.5m, Rate = 0.25m, Other = 10m });
        table.Upsert(new() { Amount = 2.5m, Rate = null, Other = 20m });

        Assert.Equal(10m, table.FindByIdOrDefault(1.5m)!.Other);
        Assert.Null(table.FindByIdOrDefault(3.5m));
        Assert.Equal(1.5m, Assert.Single(table.ListByRate(0.25m)).Amount);
        Assert.Equal(2.5m, Assert.Single(table.ListByRate(null)).Amount);
        Assert.True(table.UpdateById(2.5m, 21.5m));
        Assert.Equal(21.5m, table.FindByIdOrDefault(2.5m)!.Other);
    }

    public interface IRedeclaringPersonTable : IRelation<Person>
    {
        new void RemoveAll();
        new (long Inserted, long Updated) UpsertRange(IEnumerable<Person> items);
    }

    [Fact]
    public void RedeclaredRelationDbManipulatorMethodsAreForwarded()
    {
        using var tr = _db.StartTransaction();
        var table = tr.GetRelation<IRedeclaringPersonTable>();
        var (inserted, updated) = table.UpsertRange([
            new() { TenantId = 1, Id = 1, Name = "A" },
            new() { TenantId = 1, Id = 2, Name = "B" }
        ]);
        Assert.Equal(2, inserted);
        Assert.Equal(0, updated);
        Assert.Equal(2, table.Count);
        table.RemoveAll();
        Assert.Empty(table);
    }

    public class ItemWithComputedKey
    {
        string _name = "";

        [PrimaryKey(1)] public ulong Id { get; set; }

        public string Name
        {
            get => _name;
            set => _name = value;
        }

        [SecondaryKey("NameKey")]
        public string NameKey
        {
            get => _name;
        }

        public int Value { get; set; }
    }

    public interface IItemWithComputedKeyTable : IRelation<ItemWithComputedKey>
    {
        void UpdateById(ulong id, int value);
        ItemWithComputedKey FindByNameKey(string nameKey);
    }

    [Fact]
    public void UpdateByIdSkipsComputedFieldReturningBackingField()
    {
        using var tr = _db.StartTransaction();
        var table = tr.GetRelation<IItemWithComputedKeyTable>();
        table.Upsert(new() { Id = 1, Name = "first", Value = 1 });
        table.UpdateById(1, 42);
        var item = table.FindByNameKey("first");
        Assert.Equal("first", item.Name);
        Assert.Equal(42, item.Value);
    }

    public class TaggedItem
    {
        [PrimaryKey(1)] public ulong Id { get; set; }
        [SecondaryKey("Tags")] public IList<string> Tags { get; set; } = new List<string>();
    }

    public interface ITaggedItemTable : IRelation<TaggedItem>
    {
        IEnumerable<TaggedItem> ListByTags(IList<string> tags);
    }

    [Fact]
    public void ListBySecondaryKeyAcceptsIListParameter()
    {
        using var tr = _db.StartTransaction();
        var table = tr.GetRelation<ITaggedItemTable>();
        table.Upsert(new() { Id = 1, Tags = ["a", "b"] });
        table.Upsert(new() { Id = 2, Tags = ["c"] });
        Assert.Equal(2ul, Assert.Single(table.ListByTags(["c"])).Id);
    }
}
